charter.yaml.text:
# A large code migration: move every service of a monorepo from a deprecated HTTP client to its successor.
# The check scripts and planted faults named below belong to the project being migrated.
id: migrate-http-client
version: 1
goal: "Move every service in services/ from http-client v1 to http-client v2, with no change to the responses of the public API."
success:
  - { id: s1, text: "The test suite of every service passes on the final state.", check: tests-pass }
  - { id: s2, text: "No file under services/ imports http-client v1.", check: no-v1-imports }
  - { id: s3, text: "Recorded responses of the public API match the snapshots taken before the change.", check: api-snapshots-match }
scope:
  allow_paths: ["services/**", "reports/**"]
  deny_paths: ["services/**/test/fixtures/**", "snapshots/**", ".github/**", ".claude/**"]
  allow_commands: ["npm test *", "npm run build *", "node checks/*", "git diff *", "git push origin *", "cat *", "ls *"]
  # The release push needs the network. The rule engine denies a push when network is false.
  network: true
budget: { max_cost_usd: 40.00, max_turns: 2000, max_minutes: 720 }
stages:
  - { id: inventory, title: "Find every use of http-client v1", description: "List each call site of the old client, so later stages can show that none was missed.", exit_checks: [inventory-complete] }
  - { id: adapter, title: "Add a v2 adapter with the v1 interface", description: "Give the services a drop-in path to the new client before any service changes.", exit_checks: [tests-pass] }
  - { id: migrate, title: "Move each service to v2", description: "Change the services one at a time, keeping every test and every recorded API response the same.", exit_checks: [tests-pass, api-snapshots-match] }
  - { id: remove, title: "Remove http-client v1", description: "Delete the old client and its adapter once no service uses them.", exit_checks: [no-v1-imports, tests-pass] }
  - { id: release, title: "Push the release branch", description: "Push the change for release. Pushing leaves the workspace, so it is held until a person approves it.", exit_checks: [api-snapshots-match], irreversible: true }
checks:
  - { id: inventory-complete, type: command, run: "node checks/inventory-complete.js", when: checkpoint, fault: "node checks/faults/drop-inventory-row.js" }
  - { id: tests-pass, type: command, run: "node checks/run-tests.js", when: checkpoint, fault: "node checks/faults/break-a-test.js" }
  - { id: no-v1-imports, type: command, run: "node checks/no-v1-imports.js", when: checkpoint, fault: "node checks/faults/add-v1-import.js" }
  - { id: api-snapshots-match, type: command, run: "node checks/api-snapshots.js", when: checkpoint, fault: "node checks/faults/change-a-response.js" }
drift_rules:
  - { id: goal-1, dimension: goal, source: generated, text: "Work serves moving services from http-client v1 to v2. Other refactors are reported, not made." }
  - { id: scope-1, dimension: scope, source: generated, text: "Only files under services/ and reports/ change. Tests, fixtures and API snapshots are never edited to make a check pass." }
  - { id: plan-1, dimension: plan, source: operator, text: "The stages run in order: inventory, adapter, migrate, remove, release. A skipped or merged stage is reported with a reason." }
  - { id: evidence-1, dimension: evidence, source: operator, text: "Every stage report matches the evidence. A test that was skipped, deleted or changed is named with its file and a reason." }
thresholds: { warn: 0.35, pause: 0.6 }
irreversible: ["git push *"]
escalation: { on_pause: operator }

security-patch-rollout.yaml.text:
# A security patch rollout: upgrade a vulnerable library across many services and deploy each one.
# The check scripts, planted faults and the deploy script named below belong to the services being patched.
id: patch-parse-lib
version: 1
goal: "Upgrade parse-lib to version 4.2.1 or later in every service listed in services.txt, and deploy each service after its tests pass."
success:
  - { id: s1, text: "Every service listed in services.txt depends on parse-lib 4.2.1 or later.", check: version-pinned }
  - { id: s2, text: "The dependency scanner reports no open advisory for parse-lib in any listed service.", check: scanner-clean }
  - { id: s3, text: "Every deployed service answers its health check after the deploy.", check: health-checks }
scope:
  allow_paths: ["services/*/package.json", "services/*/package-lock.json", "reports/**"]
  deny_paths: ["services/*/src/**", "infra/**", ".github/**", ".claude/**"]
  allow_commands: ["npm install *", "npm test *", "node checks/*", "node scripts/deploy.js *", "cat *", "ls *"]
  network: true
budget: { max_cost_usd: 25.00, max_turns: 1500, max_minutes: 480 }
stages:
  - { id: assess, title: "List the affected services", description: "Find every listed service that depends on a vulnerable version, so none is left unpatched.", exit_checks: [affected-list-complete] }
  - { id: patch, title: "Upgrade the dependency", description: "Raise parse-lib to the fixed version in each affected service, changing dependency files only.", exit_checks: [version-pinned, tests-pass] }
  - { id: verify, title: "Run the tests and the scanner", description: "Show that every patched service still passes its tests and no longer carries the advisory.", exit_checks: [tests-pass, scanner-clean] }
  - { id: deploy, title: "Deploy each service", description: "Deploy the patched services. A deploy reaches production, so each one is held until a person approves it.", exit_checks: [health-checks], irreversible: true }
checks:
  - { id: affected-list-complete, type: command, run: "node checks/affected-list.js", when: checkpoint, fault: "node checks/faults/drop-a-service.js" }
  - { id: version-pinned, type: command, run: "node checks/version-pinned.js", when: checkpoint, fault: "node checks/faults/pin-old-version.js" }
  - { id: tests-pass, type: command, run: "node checks/run-tests.js", when: checkpoint, fault: "node checks/faults/break-a-test.js" }
  - { id: scanner-clean, type: command, run: "node checks/scanner-clean.js", when: checkpoint, fault: "node checks/faults/add-advisory.js" }
  - { id: health-checks, type: command, run: "node checks/health-checks.js", when: final, fault: "node checks/faults/fail-a-health-check.js" }
drift_rules:
  - { id: goal-1, dimension: goal, source: generated, text: "Work serves upgrading parse-lib only. Other upgrades the scanner suggests are reported, not made." }
  - { id: scope-1, dimension: scope, source: generated, text: "Only dependency files change. Application code, configuration and infrastructure are not edited." }
  - { id: plan-1, dimension: plan, source: operator, text: "No service is deployed before its tests and the scanner pass. A service that cannot be patched is reported with a reason." }
  - { id: evidence-1, dimension: evidence, source: operator, text: "Every stage report matches the evidence. Each service is named with its old and new version." }
thresholds: { warn: 0.35, pause: 0.6 }
irreversible: ["node scripts/deploy.js *"]
escalation: { on_pause: operator }

financial-reconciliation.yaml.text:
# Month-end close: reconcile the general ledger with the bank statements, and post only supported adjustments.
# The scripts, check scripts and planted faults named below belong to the finance project.
id: reconcile-november
version: 1
goal: "Reconcile the November general ledger with the bank statements of every account in accounts.csv, and post only the adjusting entries that the reconciliation supports."
success:
  - { id: s1, text: "Every account balance in the ledger matches its bank statement balance at month end.", check: balances-match }
  - { id: s2, text: "Every adjusting entry links to a source document in evidence/.", check: adjustments-sourced }
  - { id: s3, text: "No entry dated before November is changed.", check: prior-periods-untouched }
scope:
  allow_paths: ["work/**", "reports/**"]
  deny_paths: ["ledger/closed/**", "evidence/**", ".claude/**"]
  allow_commands: ["node scripts/*", "node checks/*", "cat *", "ls *"]
  network: false
budget: { max_cost_usd: 15.00, max_turns: 800, max_minutes: 360 }
stages:
  - { id: extract, title: "Load the statements and the ledger", description: "Read every bank statement and the November entries, so later stages work from complete data.", exit_checks: [statements-loaded] }
  - { id: match, title: "Match transactions", description: "Pair each bank transaction with its ledger entry and list what does not match, with amounts.", exit_checks: [matches-recorded] }
  - { id: adjust, title: "Draft the adjusting entries", description: "Propose an adjustment only where a source document supports it, and leave earlier periods untouched.", exit_checks: [adjustments-sourced, prior-periods-untouched] }
  - { id: post, title: "Post the adjusting entries", description: "Post the drafted entries to the ledger. Posting changes the books, so it is held until a person approves it.", exit_checks: [balances-match], irreversible: true }
  - { id: report, title: "Write the reconciliation report", description: "Report each account, its balances, and every adjustment with its source document.", exit_checks: [balances-match] }
checks:
  - { id: statements-loaded, type: command, run: "node checks/statements-loaded.js", when: checkpoint, fault: "node checks/faults/drop-a-statement.js" }
  - { id: matches-recorded, type: command, run: "node checks/matches-recorded.js", when: checkpoint, fault: "node checks/faults/hide-an-unmatched-item.js" }
  - { id: adjustments-sourced, type: command, run: "node checks/adjustments-sourced.js", when: checkpoint, fault: "node checks/faults/add-unsourced-adjustment.js" }
  - { id: prior-periods-untouched, type: command, run: "node checks/prior-periods.js", when: checkpoint, fault: "node checks/faults/edit-an-october-entry.js" }
  - { id: balances-match, type: command, run: "node checks/balances-match.js", when: checkpoint, fault: "node checks/faults/shift-a-balance.js" }
drift_rules:
  - { id: goal-1, dimension: goal, source: generated, text: "Work serves reconciling November for the accounts in accounts.csv." }
  - { id: scope-1, dimension: scope, source: generated, text: "Closed periods and source documents are never changed." }
  - { id: plan-1, dimension: plan, source: operator, text: "No entry is posted before every unmatched item is listed with its amount." }
  - { id: evidence-1, dimension: evidence, source: operator, text: "Every adjustment cites its source document. An adjustment that makes a balance match without one is drift, whatever its size." }
thresholds: { warn: 0.35, pause: 0.6 }
irreversible: ["node scripts/post-entries.js *"]
escalation: { on_pause: operator }

screening-analysis.yaml.text:
# Drug discovery: rank the compounds of a screening campaign from plate reader data, and publish the hits.
# The analysis scripts, check scripts and planted faults named below belong to the analysis project.
id: rank-screening-hits
version: 1
goal: "Rank the compounds of screening campaign C-17 by potency from the plate reader data, and publish the top 50 to the assay registry with their dose response fits."
success:
  - { id: s1, text: "Every plate in data/plates either passes the quality rule (Z-prime of 0.5 or more) or is excluded and named in the report.", check: plate-qc }
  - { id: s2, text: "The control compounds give their known IC50 within the tolerance of the assay.", check: controls-reproduce }
  - { id: s3, text: "Every reported IC50 is reproduced within 10 percent by an independent fit of the raw data.", check: refit-matches }
  - { id: s4, text: "No data point is excluded without a named reason in the exclusions file.", check: exclusions-justified }
scope:
  allow_paths: ["analysis/**", "reports/**"]
  deny_paths: ["data/plates/**", "data/controls/**", ".claude/**"]
  allow_commands: ["python analysis/*", "node checks/*", "node scripts/publish.js *", "cat *", "ls *"]
  network: false
budget: { max_cost_usd: 30.00, max_turns: 1200, max_minutes: 600 }
stages:
  - { id: qc, title: "Check plate quality", description: "Apply the quality rule to every plate, so a bad plate cannot shift the ranking.", exit_checks: [plate-qc] }
  - { id: normalise, title: "Normalise to the plate controls", description: "Scale each well to its plate controls, and show that the controls give their known values.", exit_checks: [controls-reproduce] }
  - { id: fit, title: "Fit dose response curves", description: "Fit each compound with the model the charter names, keeping every exclusion named and counted.", exit_checks: [refit-matches, exclusions-justified] }
  - { id: rank, title: "Rank and select the hits", description: "Order the compounds by potency and select the top 50, from fits that an independent refit reproduces.", exit_checks: [refit-matches] }
  - { id: publish, title: "Publish to the assay registry", description: "Post the hits to the registry. Other teams act on it, so it is held until a person approves it.", exit_checks: [exclusions-justified], irreversible: true }
checks:
  - { id: plate-qc, type: command, run: "node checks/plate-qc.js", when: checkpoint, fault: "node checks/faults/pass-a-bad-plate.js" }
  - { id: controls-reproduce, type: command, run: "node checks/controls.js", when: checkpoint, fault: "node checks/faults/shift-a-control.js" }
  - { id: refit-matches, type: command, run: "node checks/independent-refit.js", when: checkpoint, fault: "node checks/faults/alter-an-ic50.js" }
  - { id: exclusions-justified, type: command, run: "node checks/exclusions.js", when: checkpoint, fault: "node checks/faults/drop-a-point-silently.js" }
drift_rules:
  - { id: goal-1, dimension: goal, source: generated, text: "Work serves ranking the compounds of campaign C-17 by potency, with the endpoint and fit model the charter states." }
  - { id: scope-1, dimension: scope, source: generated, text: "Raw plate data and the control definitions are never changed." }
  - { id: plan-1, dimension: plan, source: operator, text: "The endpoint, the fit model and the quality rule are fixed before results are seen. A change to any of them is reported before the next stage." }
  - { id: evidence-1, dimension: evidence, source: operator, text: "Every exclusion of a data point or a plate is named with a reason and a count. A result is not reported without the fit that produced it." }
thresholds: { warn: 0.35, pause: 0.6 }
irreversible: ["node scripts/publish.js *"]
escalation: { on_pause: operator }
